package com.bct.ngtpa.apiservice.application.usecase.auth.login.otp;
import com.bct.ngtpa.apiservice.application.dto.auth.login.preauth.*;
public record LoginProtectedAuthFlowContextResult(LoginProtectedAuthFlowContextStatus status,LoginPreAuthContext context,String activeOtpChallengeId,LoginPreAuthDestination selectedDestination,String csrfTokenHash){public LoginProtectedAuthFlowContextResult{if(status==LoginProtectedAuthFlowContextStatus.VALID&&(csrfTokenHash==null||csrfTokenHash.isBlank()))throw new IllegalArgumentException("Valid protected login context requires csrfTokenHash");}public static LoginProtectedAuthFlowContextResult valid(LoginPreAuthContext context,String activeOtpChallengeId,LoginPreAuthDestination selectedDestination,String csrfTokenHash){return new LoginProtectedAuthFlowContextResult(LoginProtectedAuthFlowContextStatus.VALID,context,activeOtpChallengeId,selectedDestination,csrfTokenHash);}public static LoginProtectedAuthFlowContextResult invalid(LoginProtectedAuthFlowContextStatus status){return new LoginProtectedAuthFlowContextResult(status,null,null,null,null);}public boolean isValid(){return status==LoginProtectedAuthFlowContextStatus.VALID&&context!=null;}@Override public String toString(){return "LoginProtectedAuthFlowContextResult[status="+status+", context=<redacted>, activeOtpChallengeId=<redacted>, selectedDestination=<redacted>, csrfTokenHash=<redacted>]";}}
